import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <limits>

template <typename scalar_t>
__global__ void maxpool2d_kernel(const scalar_t* __restrict__ input,
                                 scalar_t* __restrict__ output,
                                 int N, int C, int H, int W,
                                 int kernel_h, int kernel_w,
                                 int stride_h, int stride_w,
                                 int pad_h, int pad_w,
                                 int dilation_h, int dilation_w,
                                 int H_out, int W_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int c = (idx / (W_out * H_out)) % C;
    int n = idx / (W_out * H_out * C);

    scalar_t max_val = -std::numeric_limits<scalar_t>::infinity();

    for (int kh = 0; kh < kernel_h; ++kh) {
        int h_in = h_out * stride_h - pad_h + kh * dilation_h;
        if (h_in < 0 || h_in >= H) continue;
        for (int kw = 0; kw < kernel_w; ++kw) {
            int w_in = w_out * stride_w - pad_w + kw * dilation_w;
            if (w_in < 0 || w_in >= W) continue;
            scalar_t val = input[ ((n * C + c) * H + h_in) * W + w_in ];
            if (val > max_val) max_val = val;
        }
    }
    output[ ((n * C + c) * H_out + h_out) * W_out + w_out ] = max_val;
}

torch::Tensor maxpool2d_forward(torch::Tensor input,
                                int64_t kernel_size,
                                int64_t stride,
                                int64_t padding,
                                int64_t dilation) {
    const auto N = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);

    const int64_t kernel_h = kernel_size;
    const int64_t kernel_w = kernel_size;
    const int64_t stride_h = stride;
    const int64_t stride_w = stride;
    const int64_t pad_h = padding;
    const int64_t pad_w = padding;
    const int64_t dilation_h = dilation;
    const int64_t dilation_w = dilation;

    const int64_t H_out = (H + 2 * pad_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    const int64_t W_out = (W + 2 * pad_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    const int threads = 256;
    const int total = N * C * H_out * W_out;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_FLOAT(input.scalar_type(), "maxpool2d_forward", ([&] {
        maxpool2d_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N, C, H, W,
            kernel_h, kernel_w,
            stride_h, stride_w,
            pad_h, pad_w,
            dilation_h, dilation_w,
            H_out, W_out);
    }));

    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &maxpool2d_forward, "MaxPool2d forward (CUDA)");
}
'''

maxpool2d_cuda = load_inline(name='maxpool2d_cuda',
                             cpp_sources='',
                             cuda_sources=cuda_source,
                             functions=['forward'],
                             verbose=False)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool2d_cuda.forward(x,
                                      self.kernel_size,
                                      self.stride,
                                      self.padding,
                                      self.dilation)

# Example usage (can be removed in production)
if __name__ == "__main__":
    batch_size = 32
    channels = 64
    height = 512
    width = 512
    ks = 4
    st = 1
    pad = 1
    dil = 1

    model = ModelNew(ks, st, pad, dil).cuda().half()
    x = torch.rand(batch_size, channels, height, width, device='cuda', dtype=torch.half)
    y = model(x)
    print(y.shape)  # Expected: (32, 64, 511, 511)
